"use client";
/* PixelType, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function PixelType(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("core"); }, []);
  return React.createElement("piix-type", piixAttrs(props));
}

export default PixelType;
